import { memo } from 'react';

/** Deterministic particle layout (no randomness on re-render). */
const PARTICLES = Array.from({ length: 26 }, (_, i) => {
  const a = (i * 7919) % 1000;
  return {
    left: `${(a * 37) % 100}%`,
    size: 2 + (a % 3),
    delay: `${-((a * 13) % 18)}s`,
    duration: `${14 + (a % 10)}s`,
    drift: `${((a % 7) - 3) * 12}px`,
  };
});

/**
 * Cinematic night-city background for the signed-in app (dark theme): an original city skyline
 * with a caped hero on a far-left rooftop (public/backgrounds/cyber-city.svg, generated by
 * scripts/generate-cyber-city.mjs), slow light rays, floating particles, and a scrim that keeps
 * the centre and right side dark so cards stay readable.
 *
 * Only transform/opacity animate (GPU-composited); "Background effects: Off" hides it and reduced
 * motion stops the loops (see index.css).
 */
export const CityBackdrop = memo(function CityBackdrop() {
  return (
    <div
      aria-hidden
      className="bg-effect city-backdrop pointer-events-none fixed inset-0 -z-20 overflow-hidden"
    >
      <img
        src="/backgrounds/cyber-city.svg"
        alt=""
        decoding="async"
        className="city-image city-image-night absolute inset-0 h-full w-full object-cover object-left-bottom"
      />
      <img
        src="/backgrounds/cyber-city-day.svg"
        alt=""
        decoding="async"
        loading="lazy"
        className="city-image city-image-day absolute inset-0 h-full w-full object-cover object-left-bottom"
      />
      <div className="city-ray city-ray-1" />
      <div className="city-ray city-ray-2" />
      <div className="city-scrim absolute inset-0" />
      <div className="absolute inset-0">
        {PARTICLES.map((p, i) => (
          <span
            key={i}
            className="city-particle"
            style={
              {
                left: p.left,
                width: p.size,
                height: p.size,
                animationDelay: p.delay,
                animationDuration: p.duration,
                '--drift': p.drift,
              } as React.CSSProperties
            }
          />
        ))}
      </div>
    </div>
  );
});
